#!/usr/bin/env node
// Builds jam-cards.js from src/ (plain concatenation inside ONE IIFE, no deps) and writes preview/fixtures/index.js.
//   node tools/bundle.mjs          write jam-cards.js + preview/fixtures/index.js + preview/looks.css
//   node tools/bundle.mjs --check  exit 1 if a generated file is stale (also the jam-theme YAML when ../jam-theme exists)
// Order: src/header.js (opens the IIFE), generated fonts chunk (FONT_CSS), generated tokens chunk (TOKEN_CSS, JAM_TOKENS), src/core.js,
// src/looks/*.js (look packs, by name: registerLook), src/cards/*.js (by name), src/editors.js (visual editor statics), src/footer.js (closes it).
// Fonts: fonts/*.woff2 (OFL, latin subset from Google Fonts) are embedded as base64 data: URIs in FONT_CSS; core.js injects it once into document.head.
// Tokens: tokens/ (the single token source) -> TOKEN_CSS (BASE_CSS :host fallbacks = the Poster dark values) and
// preview/looks.css; tools/themes.mjs writes the theme YAML from the same source.
import fs from "node:fs";
import path from "node:path";
import {fileURLToPath} from "node:url";
import {hostCss, looksCss, copyTokens} from "../tokens/index.mjs";
import {staleThemes} from "./themes.mjs";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const p = (...a) => path.join(ROOT, ...a);
const read = f => fs.readFileSync(p(f), "utf8");
const list = dir => fs.readdirSync(p(dir)).filter(f => f.endsWith(".js") && f !== "index.js").sort();

const BANNER = "/* GENERATED from src/ by tools/bundle.mjs — edit src/, then run node tools/bundle.mjs */\n";
// Same unicode-range Google Fonts uses for its "latin" subset (covers ° · × − – — … µ ± ³; arrows/≤/≈ fall back to system fonts).
const LATIN = "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD";
const FONTS = [
  {family: "Londrina Solid", weight: "900", file: "fonts/londrina-solid-900-latin.woff2"},
  {family: "Jost", weight: "400 600", file: "fonts/jost-var-latin.woff2"}, // variable font, same weight range as before (400/500/600)
];
const fontCss = FONTS.map(f => `@font-face{font-family:"${f.family}";font-style:normal;font-weight:${f.weight};font-display:swap;` +
  `src:url(data:font/woff2;base64,${fs.readFileSync(p(f.file)).toString("base64")}) format("woff2");unicode-range:${LATIN}}`).join("\n");
const fontChunk = "/* GENERATED by tools/bundle.mjs from fonts/*.woff2 (SIL OFL 1.1, see fonts/OFL-*.txt); FONT_LATIN = the unicode-range of\n" +
  "   the latin subsets, also used by the look packs' URL @font-face rules (core.js lookFontCss) */\n" +
  `const FONT_CSS = ${JSON.stringify(fontCss)};\nconst FONT_LATIN = ${JSON.stringify(LATIN)};\n`;

const tokenChunk = "/* GENERATED by tools/bundle.mjs from tokens/ (registry + Poster dark values): BASE_CSS :host declarations and the\n" +
  "   --jam-* names that body layers (openSheet, jam-screensaver) copy from their card */\n" +
  `const TOKEN_CSS = ${JSON.stringify(hostCss() + "\n")};\n` +
  `const JAM_TOKENS = ${JSON.stringify(copyTokens())};\n`;

const parts = ["src/header.js", "(fonts)", "(tokens)", "src/core.js", ...list("src/looks").map(f => "src/looks/" + f), ...list("src/cards").map(f => "src/cards/" + f), "src/editors.js", "src/footer.js"];
const bundle = BANNER + parts.map(f => { const s = f === "(fonts)" ? fontChunk : f === "(tokens)" ? tokenChunk : read(f); return s.endsWith("\n") ? s : s + "\n"; }).join("\n");

const fixtures = list("preview/fixtures");
const fixIndex = "// GENERATED by tools/bundle.mjs — lists preview/fixtures/*.js in name order. Loaded synchronously by index.html.\n" +
  `for (const f of ${JSON.stringify(fixtures)}) document.write('<script src="fixtures/' + f + '"><\\/script>');\n`;

const out = {"jam-cards.js": bundle, "preview/fixtures/index.js": fixIndex, "preview/looks.css": looksCss()};
if (process.argv.includes("--check")) {
  const stale = Object.entries(out).filter(([f, s]) => !fs.existsSync(p(f)) || read(f) !== s).map(([f]) => f)
    .concat(staleThemes(undefined, true).map(f => path.relative(ROOT, f) + " (node tools/themes.mjs)"));
  if (stale.length) { console.error("STALE: " + stale.join(", ") + " — run node tools/bundle.mjs"); process.exit(1); }
  console.log("bundle up to date");
} else {
  for (const [f, s] of Object.entries(out)) fs.writeFileSync(p(f), s);
  console.log(`wrote jam-cards.js (${parts.length} parts) + preview/fixtures/index.js (${fixtures.length} fixtures) + preview/looks.css`);
}
